%[text] # LCC Trap Calculations
%[text] ## Functions & Variables
sympref('FloatingPointOutput',true);
close all;
%[text] ### Initialize Variables
%[text] Constants
u0 = 4*pi*10^-7; % permeability of free space
%[text] Frequency for each nuclei of interest
f1H  = 123.2030E6; % Hz
f31P = 49.8719E6; % Hz

w1H = 2*pi*f1H; % rad/s
w31P = 2*pi*f31P; % rad/s
%[text] ### Define Functions
%[text] Reactance of a capacitor
syms X_C(w,C)
X_C(w,C) = -1/(w*C) % Ohms %[output:58b0f21a]
%[text] Reactance of an inductor
syms X_L(w,L)
X_L(w,L) = w*L % Ohms %[output:05f4ccc1]
%[text] Reactance of an LCC trap
syms X_tr(w,C_s,C_p,L_tr)
X_tr(w,C_s,C_p,L_tr) = 1/(1/X_C(w,C_p) + 1/(X_L(w,L_tr) + X_C(w,C_s))) % Ohms %[output:594a68cc]
%[text] Inductance of an air-core solenoid
syms L_sol(u_0,r,N,l)
L_sol(u_0,r,N,l) = (u_0*(pi*r^2)*N^2)/l % H %[output:30d53630]
%[text] Clear symbolic variables
clear w C C_s C_p L_tr u_0 r N l L
%[text] ## Experimental Data
%[text] ### Inputs
%[text] Coil inductance calculations
Cexp = [110E-12, 62E-12]; % Capacitance at each trap location to tune coil
wexp = 2*pi*[38E6, 50E6]; % Resonant frequency with given capacitance
Lcoil = mean(1./((wexp.^2).*(Cexp./4))) % Coil inductance %[output:8ef23aff]
%[text] Theoretical capacitance to resonate at given frequencies
N = 4 % number of tuning capacitors %[output:62d13d6f]
C1H  = N/((w1H^2)*Lcoil) % F %[output:875d504e]
C31P = N/((w31P^2)*Lcoil) % F %[output:40d3adf3]
%[text] Reactances based off the capacitors
X1H = -double(X_C(w1H, C1H)) % Ohms %[output:0c2308a0]
X31P = -double(X_C(w31P, C31P)) % Ohms %[output:81959468]
%[text] ### Outputs
%[text] Trap minimum and maximum inductance
Lmin = N/((C31P - C1H)*(w1H^2 - w31P^2)) % H %[output:2131b58e]
Lmax = 500/w1H % H %[output:0bd8addc]
%[text] Select reasonable inductance value
Ltr = 220E-9 % H %[output:11659bef]
%[text] Trap capacitance calculations
Cp_th(1) = (C31P + C1H)/2 + sqrt((C31P - C1H)^2/4 - (C31P - C1H)/(Ltr*(w1H^2 - w31P^2))); % F
Cp_th(2) = (C31P + C1H)/2 - sqrt((C31P - C1H)^2/4 - (C31P - C1H)/(Ltr*(w1H^2 - w31P^2))) % F %[output:853a21ff]
Cs_th = (C1H - Cp_th)./(w1H^2*Ltr*(C1H - Cp_th) + 1) % F %[output:1eabc324]
%[text] Resonance of each trap
ftr = 1E-6./(2.*pi.*sqrt(Ltr.*(Cs_th.*Cp_th)./(Cs_th + Cp_th))) % Hz %[output:76172bc8]
%[text] Select whichever solution is farther from 1H
if abs(ftr(1) - f1H) > abs(ftr(2) - f1H)
    sol = 1;
else
    sol = 2;
end
%%
%[text] ### Testing
close all
%[text] Testing ranges
y = [-180 0];
Cs = round(Cs_th(sol)*1E12)/1E12;
Cp = round(Cp_th(sol)*1E12)/1E12;
w = (39:0.5:133).*(2*pi*1E6);
Xcoil = X_L(w,Lcoil)./4;
%[text] #### Reactance Matching (varying Cs)
idx = 1;
Cidx = Cs/1E-12;
Cidx = (Cidx-(3*idx):idx:Cidx+(3*idx)).*1E-12;

figure; plot(w./(2*pi*1E6), -Xcoil,'black','DisplayName','X_{coil}'); xlabel('MHz');ylabel('Ohms'); xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([y(1), y(2)]); %[output:167c2307]
hold on %[output:167c2307]
for i = 1:length(Cidx)
    Xtr = X_tr(w,Cidx(i),Cp,Ltr);
    plot(w./(2*pi*1E6), Xtr,'DisplayName',['X_{tr} (C_s=' num2str(Cidx(i)/1E-12) 'pF)']); %[output:167c2307]
end
xline(w1H/(2*pi*1E6),'--','HandleVisibility','off') %[output:167c2307]
xline(w31P/(2*pi*1E6),'--','HandleVisibility','off') %[output:167c2307]
legend('Location', 'southwest') %[output:167c2307]
title('Reactance vs. Frequency (varying C_s)'); %[output:167c2307]
%[text] #### Reactance Matching (varying Cp)
idx = 1;
Cidx = Cp/1E-12;
Cidx = (Cidx-(3*idx):idx:Cidx+(3*idx)).*1E-12;

figure; plot(w./(2*pi*1E6), -Xcoil,'black','DisplayName','X_{coil}'); xlabel('MHz');ylabel('Ohms'); xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([y(1), y(2)]); %[output:252db3bc]
hold on %[output:252db3bc]
for i = 1:length(Cidx)
    Xtr = X_tr(w,Cs,Cidx(i),Ltr);
    plot(w./(2*pi*1E6), Xtr,'DisplayName',['X_{tr} (C_p=' num2str(Cidx(i)/1E-12) 'pF)']); %[output:252db3bc]
end
xline(w1H/(2*pi*1E6),'--','HandleVisibility','off') %[output:252db3bc]
xline(w31P/(2*pi*1E6),'--','HandleVisibility','off') %[output:252db3bc]
legend('Location', 'southwest') %[output:252db3bc]
title('Reactance vs. Frequency (varying C_p)'); %[output:252db3bc]
%[text] #### Reactance Matching (varying L)
idx = 10;
Lidx = (round(Ltr*1E9)-(3*idx):idx:round(Ltr*1E9)+(3*idx)).*1E-9;

figure; plot(w./(2*pi*1E6), -Xcoil,'black','DisplayName','X_{coil}'); xlabel('MHz');ylabel('Ohms'); xlim([min(w)/(2*pi*1E6) max(w)/(2*pi*1E6)]); ylim([y(1), y(2)]); %[output:65aadf0a]
hold on %[output:65aadf0a]
for i = 1:length(Lidx)
    Xtr = X_tr(w,Cs,Cp,Lidx(i));
    plot(w./(2*pi*1E6), Xtr,'DisplayName',['X_{tr} (L=' num2str(Lidx(i)/1E-9) 'nH)']); %[output:65aadf0a]
end
xline(w1H/(2*pi*1E6),'--','HandleVisibility','off') %[output:65aadf0a]
xline(w31P/(2*pi*1E6),'--','HandleVisibility','off') %[output:65aadf0a]
legend('Location', 'southwest') %[output:65aadf0a]
title('Reactance vs. Frequency (varying L)'); %[output:65aadf0a]
%%
